<?php session_start();require_once 'config/conexao.php';require_once 'config/auth.php';exigir_cargo(['administrador','gerente','funcionario']);$nivel=$_SESSION['usuario']['nivel'];if($_SERVER['REQUEST_METHOD']==='POST'&&in_array($nivel,['administrador','gerente'],true)){ $st=$_POST['status']??'';if(in_array($st,['aberta','em_producao','concluida','cancelada'],true)){$pdo->prepare('UPDATE vendas SET status=? WHERE id=?')->execute([$st,(int)$_POST['id']]);flash('Status atualizado.');}header('Location: vendas.php');exit;}
$sql='SELECT v.*,u.nome AS vendedor FROM vendas v JOIN usuarios u ON u.id=v.usuario_id';if($nivel==='funcionario'){$sql.=' WHERE v.usuario_id='.(int)$_SESSION['usuario']['id'];}$sql.=' ORDER BY v.criado_em DESC';$vendas=$pdo->query($sql)->fetchAll(); ?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vendas e pedidos</title><link rel="stylesheet" href="style.css"></head><body><main class="app"><header class="topbar"><h2>Vendas e pedidos</h2><a class="link-sair" href="painel.php">← Painel</a></header><section class="content"><?php mostrar_flash();?><?php if($nivel==='funcionario'):?><a class="button-link" href="nova_venda.php">+ Registrar venda</a><?php endif;?><div class="table-wrap"><table><thead><tr><th>#</th><th>Cliente</th><th>Vendedor</th><th>Total</th><th>Status</th><th>Data</th><?php if($nivel!=='funcionario'):?><th>Atualizar</th><?php endif;?></tr></thead><tbody><?php foreach($vendas as $v):?><tr><td><?=$v['id']?></td><td><?=h($v['cliente']?:'—')?></td><td><?=h($v['vendedor'])?></td><td>R$ <?=number_format($v['total'],2,',','.')?></td><td><?=h($v['status'])?></td><td><?=date('d/m/Y H:i',strtotime($v['criado_em']))?></td><?php if($nivel!=='funcionario'):?><td><form method="post" class="inline"><input type="hidden" name="id" value="<?=$v['id']?>"><select name="status"><option value="aberta">Aberta</option><option value="em_producao" <?=$v['status']==='em_producao'?'selected':''?>>Em produção</option><option value="concluida" <?=$v['status']==='concluida'?'selected':''?>>Concluída</option><option value="cancelada" <?=$v['status']==='cancelada'?'selected':''?>>Cancelada</option></select><button class="mini">Salvar</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></section></main></body></html>